mapper.update:
UPDATE orders
SET status = 1,
    pay_time = NOW(),
    transaction_id = #{transactionId}
WHERE order_no = #{orderNo}
  AND user_id = #{userId}
  AND status = 0

mapper.select:
SELECT * FROM orders
WHERE user_id = #{userId}
  AND product_id = #{productId}
  AND status IN (0, 1)
LIMIT 1
